262	/****************************************************************************
263	 * Name: nrf53_ioctl
264	 *
265	 * Description:
266	 *   All ioctl calls will be routed through this method
267	 *
268	 ****************************************************************************/
269	
270	static int sifli_ioctl(struct file *filep, int cmd, unsigned long arg)
271	{
272	  struct inode         *inode;
273	  struct uart_dev_s    *dev;
274	  struct sifli_uart    *uart;
275	#ifdef CONFIG_SERIAL_TERMIOS
276	  struct serial_configure *config;
277	#endif
278	  int                   ret    = OK;
279	
280	  if (filep == NULL || filep->f_inode == NULL)
281	    {
282	      return -EINVAL;
283	    }
284	
285	  inode = filep->f_inode;
286	  dev   = inode->i_private;
287	  uart  = (struct sifli_uart *)dev->priv;
288	#ifdef CONFIG_SERIAL_TERMIOS
289	  config = &uart->ser_cfg;
290	#endif
291	
292	  switch (cmd)
293	    {
294	#ifdef CONFIG_SERIAL_TERMIOS
295	      case TCGETS:
296	        {
297	          struct termios *termiosp = (struct termios *)arg;
298	
299	          if (!termiosp)
300	            {
301	              ret = -EINVAL;
302	              break;
303	            }
304	
305	          termiosp->c_cflag = ((config->parity != 0) ? PARENB : 0)
306	                              | ((config->parity == 1) ? PARODD : 0)
307	                              | ((config->stop_bits==STOP_BITS_2) ? CSTOPB : 0) |
308	#ifdef CONFIG_SERIAL_OFLOWCONTROL
309	                              ((config->hwfc&RT_SERIAL_HWFC_CTS) ? CCTS_OFLOW : 0) |
310	#endif
311	#ifdef CONFIG_SERIAL_IFLOWCONTROL
312	                              ((config->hwfc&RT_SERIAL_HWFC_RTS) ? CRTS_IFLOW : 0) |
313	#endif
314	                              CS8;
315	
316	          cfsetispeed(termiosp, config->baud_rate);
317	
318	          break;
319	        }
320	
321	      case TCSETS:
322	        {
323	          struct termios *termiosp = (struct termios *)arg;
324	
325	          if (!termiosp)
326	            {
327	              ret = -EINVAL;
328	              break;
329	            }
330	
331	          /* Perform some sanity checks before accepting any changes */
332	
333	          if ((termiosp->c_cflag & CSIZE) != CS8)
334	            {
335	              ret = -EINVAL;
336	              break;
337	            }
338	
339	#ifndef HAVE_UART_STOPBITS
340	          if ((termiosp->c_cflag & CSTOPB) != 0)
341	            {
342	              ret = -EINVAL;
343	              break;
344	            }
345	#endif
346	
347	          if (termiosp->c_cflag & PARODD)
348	            {
349	              ret = -EINVAL;
350	              break;
351	            }
352	
353	          /* TODO: CCTS_OFLOW and CRTS_IFLOW */
354	
355	          /* Parity */
356	
357	          if (termiosp->c_cflag & PARENB)
358	            {
359	              config->parity = (termiosp->c_cflag & PARODD) ? 1 : 2;
360	            }
361	          else
362	            {
363	              config->parity = 0;
364	            }
365	
366	#ifdef HAVE_UART_STOPBITS
367	          /* Stop bits */
368	
369	          config->stop_bits = (termiosp->c_cflag & CSTOPB) ? STOP_BITS_2:STOP_BITS_1;
370	#endif
371	
372	          /* Note that only cfgetispeed is used because we have knowledge
373	           * that only one speed is supported.
374	           */
375	
376	          config->baud_rate = cfgetispeed(termiosp);
377	
378	          /* Effect the changes */
379	
380	          sifli_setup(dev);
381	
382	          break;
383	        }
384	#endif
385	
386	      default:
387	        {
388	          /* FIONREAD / poll look at the SW ring only. Harvest bounce first. */
389	          sifli_uart_dma_poll(uart);
390	          ret = -ENOTTY;
391	          break;
392	        }
393	    }
394	
395	  return ret;
396	}
