702	static void sifli_uart_dma_recover_log(uint32_t n, int inplace)
703	{
704	    if (up_interrupt_context())
705	    {
706	        return;
707	    }
708	
709	    if (n <= 3u || (n & 0x1fu) == 0u)
710	    {
711	        syslog(LOG_WARNING, "uart: RX DMA recover n=%u inplace=%d\n",
712	               (unsigned)n, inplace);
713	    }
714	}
715	
716	/** Restart circular RX on the pinned channel; do not HAL_DMA_Abort (frees pool). */
717	static int sifli_uart_dma_restart_circ(struct sifli_uart *uart)
718	{
719	    DMA_HandleTypeDef *hdma = uart->handle.hdmarx;
720	    USART_TypeDef *usart = uart->handle.Instance;
721	    uint16_t size = uart->dma_rx.xfer_size;
722	
723	    if (hdma == NULL || hdma->Instance == NULL ||
724	        hdma->DmaBaseAddress == NULL || size == 0 ||
725	        uart->dma_rx.bounce == NULL || usart == NULL)
726	    {
727	        return -ENODEV;
728	    }
729	
730	    CLEAR_BIT(usart->CR3, USART_CR3_DMAR);
731	
732	    __HAL_DMA_DISABLE(hdma);
733	    hdma->DmaBaseAddress->IFCR = (DMA_ISR_GIF1 << (hdma->ChannelIndex & 0x1cU));
734	
735	    /* TE recover clears TCIE/HTIE/TEIE and may drop CIRC. Reload the
736	     * bounce target so GNSS can start again after an error.
737	     */
738	    hdma->Init.Mode = DMA_CIRCULAR;
739	    SET_BIT(hdma->Instance->CCR, DMA_CIRCULAR);
740	    hdma->Instance->CPAR = (uint32_t)&usart->RDR;
741	    hdma->Instance->CM0AR = (uint32_t)uart->dma_rx.bounce;
742	    __HAL_DMA_SET_COUNTER(hdma, size);
743	    __HAL_DMA_ENABLE_IT(hdma, (DMA_IT_TC | DMA_IT_HT | DMA_IT_TE));
744	
745	    uart->dma_rx.pos = 0;
746	    __HAL_DMA_ENABLE(hdma);
747	    SET_BIT(usart->CR3, USART_CR3_DMAR);
748	    SET_BIT(usart->CR3, USART_CR3_EIE);
749	
750	    hdma->State = HAL_DMA_STATE_BUSY;
751	    hdma->Lock = HAL_UNLOCKED;
752	    hdma->ErrorCode = HAL_DMA_ERROR_NONE;
753	    uart->handle.RxState = HAL_UART_STATE_BUSY_RX;
754	    uart->handle.Lock = HAL_UNLOCKED;
755	    uart->handle.ErrorCode = HAL_UART_ERROR_NONE;
756	    uart->handle.pRxBuffPtr = uart->dma_rx.bounce;
757	    uart->handle.RxXferSize = size;
758	    uart->dma_rx.need_recover = 0;
759	    sifli_uart_dma_irq_sync(uart);
760	    __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_IDLE);
761	    return sifli_uart_dma_hw_alive(uart) ? OK : -EIO;
762	}
763	
764	static void sifli_uart_dma_recover(struct sifli_uart *uart)
765	{
766	    static uint32_t recover_n;
767	    irqstate_t flags;
768	    int inplace = 0;
769	
770	    flags = enter_critical_section();
771	    if (uart->dma_rx.recovering)
772	    {
773	        leave_critical_section(flags);
774	        return;
775	    }
776	
777	    uart->dma_rx.recovering = 1;
778	    sifli_uart_dma_harvest(uart);
779	    if (sifli_uart_dma_restart_circ(uart) == OK)
780	    {
781	        sifli_uart_rx_drain_fifo(uart);
782	        inplace = 1;
783	    }
784	    else if (!up_interrupt_context())
785	    {
786	        sifli_uart_dma_stop(uart);
787	        sifli_uart_rx_drain_fifo(uart);
788	        uart->dma_rx.xfer_size = 0;
789	        uart->dma_rx.pos = 0;
790	        uart->dma_rx.need_recover = 0;
791	        (void)sifli_uart_dma_arm(uart);
792	    }
793	    else
794	    {
795	        /* Abort+Init from UART ISR re-enters HAL_DMA and can hang GNSS. */
796	        uart->dma_rx.need_recover = 1;
797	    }
798	
799	    uart->dma_rx.recovering = 0;
800	    recover_n++;
801	    leave_critical_section(flags);
802	    sifli_uart_dma_recover_log(recover_n, inplace);
803	}
804	
805	static void sifli_uart_dma_poll(struct sifli_uart *uart)
806	{
807	    if (!uart->uart_rx_dma_flag)
808	    {
809	        return;
810	    }
811	
812	    sifli_uart_dma_harvest(uart);
813	    if (uart->dma_rx.need_recover || !sifli_uart_dma_hw_alive(uart))
814	    {
815	        sifli_uart_dma_recover(uart);
816	    }
817	}
