141	static rt_err_t sifli_configure(struct rt_serial_device *serial, struct serial_configure *cfg)
142	{
143	    struct sifli_uart *uart;
144	    RT_ASSERT(serial != RT_NULL);
145	    RT_ASSERT(cfg != RT_NULL);
146	    uart = (struct sifli_uart *)serial->parent.user_data;
147	    RT_ASSERT(uart != RT_NULL);
148	
149	    uart->handle.Instance          = uart->config->Instance;
150	    uart->handle.Init.BaudRate     = cfg->baud_rate;
151	    uart->handle.Init.HwFlowCtl    = cfg->hwfc;
152	    uart->handle.Init.HwFlowCtl    <<= USART_CR3_RTSE_Pos;
153	    uart->handle.Init.Mode         = UART_MODE_TX_RX;
154	    uart->handle.Init.OverSampling = UART_OVERSAMPLING_16;
155	
156	    if (cfg->parity && cfg->data_bits < DATA_BITS_9)
157	        cfg->data_bits++;                           // parity is part of data
158	
159	    switch (cfg->data_bits)
160	    {
161	    case DATA_BITS_6:
162	        uart->handle.Init.WordLength = UART_WORDLENGTH_6B;
163	        break;
164	    case DATA_BITS_7:
165	        uart->handle.Init.WordLength = UART_WORDLENGTH_7B;
166	        break;
167	    case DATA_BITS_8:
168	        uart->handle.Init.WordLength = UART_WORDLENGTH_8B;
169	        break;
170	    case DATA_BITS_9:
171	        uart->handle.Init.WordLength = UART_WORDLENGTH_9B;
172	        break;
173	    default:
174	        uart->handle.Init.WordLength = UART_WORDLENGTH_8B;
175	        break;
176	    }
177	    switch (cfg->stop_bits)
178	    {
179	    case STOP_BITS_1:
180	        uart->handle.Init.StopBits   = UART_STOPBITS_1;
181	        break;
182	    case STOP_BITS_2:
183	        uart->handle.Init.StopBits   = UART_STOPBITS_2;
184	        break;
185	    case STOP_BITS_3:
186	        uart->handle.Init.StopBits   = UART_STOPBITS_0_5;
187	        break;
188	    case STOP_BITS_4:
189	        uart->handle.Init.StopBits   = UART_STOPBITS_1_5;
190	        break;
191	    default:
192	        uart->handle.Init.StopBits   = UART_STOPBITS_1;
193	        break;
194	    }
195	    switch (cfg->parity)
196	    {
197	    case PARITY_NONE:
198	        uart->handle.Init.Parity     = UART_PARITY_NONE;
199	        break;
200	    case PARITY_ODD:
201	        uart->handle.Init.Parity     = UART_PARITY_ODD;
202	        break;
203	    case PARITY_EVEN:
204	        uart->handle.Init.Parity     = UART_PARITY_EVEN;
205	        break;
206	    default:
207	        uart->handle.Init.Parity     = UART_PARITY_NONE;
208	        break;
209	    }
210	
211	    if (HAL_UART_Init(&uart->handle) != HAL_OK)
212	    {
213	        return -RT_ERROR;
214	    }
215	
216	    return RT_EOK;
217	}
