219	static rt_err_t sifli_control(struct rt_serial_device *serial, int cmd, void *arg)
220	{
221	    struct sifli_uart *uart;
222	#ifdef RT_SERIAL_USING_DMA
223	    rt_ubase_t ctrl_arg = (rt_ubase_t)arg;
224	#endif
225	
226	    RT_ASSERT(serial != RT_NULL);
227	    uart = (struct sifli_uart *)serial->parent.user_data;
228	    RT_ASSERT(uart != RT_NULL);
229	
230	    switch (cmd)
231	    {
232	    /* disable interrupt */
233	    case RT_DEVICE_CTRL_CLR_INT:
234	        /* disable rx irq */
235	        NVIC_DisableIRQ(uart->config->irq_type);
236	        /* disable interrupt */
237	        __HAL_UART_DISABLE_IT(&(uart->handle), UART_IT_RXNE);
238	        if (arg == (void *) RT_DEVICE_FLAG_DMA_RX)
239	        {
240	            uart->dma_rx.last_index = 0;
241	            //HAL_UART_DMAStop(&uart->handle);
242	            HAL_UART_AbortReceive_IT(&uart->handle);
243	#ifndef DMA_SUPPORT_DYN_CHANNEL_ALLOC
244	            NVIC_DisableIRQ(uart->config->dma_rx->dma_irq);
245	#endif /* !DMA_SUPPORT_DYN_CHANNEL_ALLOC */
246	            __HAL_UART_DISABLE_IT(&(uart->handle), UART_IT_IDLE);
247	            __HAL_UART_CLEAR_IT(&(uart->handle), UART_IT_IDLE);
248	
249	        }
250	        else if (arg == (void *) RT_DEVICE_FLAG_DMA_TX)
251	        {
252	            //HAL_UART_DMAStop(&uart->handle);
253	            HAL_UART_AbortTransmit_IT(&uart->handle);
254	#ifndef DMA_SUPPORT_DYN_CHANNEL_ALLOC
255	            NVIC_DisableIRQ(uart->config->dma_tx->dma_irq);
256	#endif /* !DMA_SUPPORT_DYN_CHANNEL_ALLOC */
257	        }
258	        break;
259	    /* enable interrupt */
260	    case RT_DEVICE_CTRL_SET_INT:
261	        if (RT_DEVICE_FLAG_INT_RX == (uint32_t)arg)
262	        {
263	            /* enable rx irq */
264	            NVIC_EnableIRQ(uart->config->irq_type);
265	            /* enable interrupt */
266	            __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_RXNE);
267	        }
268	        break;
269	
270	#ifdef RT_SERIAL_USING_DMA
271	    case RT_DEVICE_CTRL_CONFIG:
272	        if (ctrl_arg == RT_DEVICE_FLAG_DMA_RX)
273	        {
274	            // Clear FIFO
275	            uart->handle.Instance->RQR |= USART_RQR_RXFRQ;
276	            RT_ASSERT(serial != RT_NULL);
277	
278	            struct rt_serial_rx_fifo *rx_fifo = (struct rt_serial_rx_fifo *)serial->serial_rx;
279	            sifli_dma_transmit(serial, rx_fifo->buffer, serial->config.bufsz, RT_SERIAL_DMA_RX);
280	            uart->dma_rx.last_index = 0;
281	        }
282	        break;
283	#endif
284	    }
285	    sifli_configure(serial, &(serial->config));
286	    return RT_EOK;
287	}
