289	static int sifli_putc(struct rt_serial_device *serial, char c)
290	{
291	    struct sifli_uart *uart;
292	    RT_ASSERT(serial != RT_NULL);
293	    rt_base_t level;
294	    HAL_UART_LOCK_DEF();
295	
296	    uart = (struct sifli_uart *)serial->parent.user_data;
297	
298	    HAL_UART_LOCK(&uart->handle);
299	
300	    level = rt_hw_interrupt_disable();
301	    UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_TC);
302	    __HAL_UART_PUTC(&uart->handle, c);
303	    while (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TC) == RESET);
304	    rt_hw_interrupt_enable(level);
305	
306	    HAL_UART_UNLOCK(&uart->handle);
307	
308	    return 1;
309	}
