329	static rt_size_t sifli_dma_transmit(struct rt_serial_device *serial, rt_uint8_t *buf, rt_size_t size, int direction)
330	{
331	    struct sifli_uart *uart;
332	    IRQn_Type irq;
333	
334	    RT_ASSERT(serial != RT_NULL);
335	    uart = (struct sifli_uart *)serial->parent.user_data;
336	    RT_ASSERT(uart != RT_NULL);
337	    if (direction == RT_SERIAL_DMA_RX)
338	    {
339	        __HAL_LINKDMA(&(uart->handle), hdmarx, uart->dma_rx.handle);
340	        uart->handle.hdmarx->Instance = uart->config->dma_rx->Instance;
341	        uart->handle.hdmarx->Init.Request = uart->config->dma_rx->request;
342	        irq = uart->config->dma_rx->dma_irq;
343	    }
344	    else
345	    {
346	        __HAL_LINKDMA(&(uart->handle), hdmatx, uart->dma_tx.handle);
347	        uart->handle.hdmatx->Instance = uart->config->dma_tx->Instance;
348	        uart->handle.hdmatx->Init.Request = uart->config->dma_tx->request;
349	        irq = uart->config->dma_tx->dma_irq;
350	    }
351	#ifndef DMA_SUPPORT_DYN_CHANNEL_ALLOC
352	    HAL_NVIC_SetPriority(irq, 0, 0);
353	    HAL_NVIC_EnableIRQ(irq);
354	#endif /* !DMA_SUPPORT_DYN_CHANNEL_ALLOC */
355	    if (direction == RT_SERIAL_DMA_RX)  // For RX DMA, also need to enable UART IRQ.
356	    {
357	        __HAL_UART_ENABLE_IT(&(uart->handle), UART_IT_IDLE);
358	        HAL_NVIC_SetPriority(uart->config->irq_type, 1, 0);
359	        HAL_NVIC_EnableIRQ(uart->config->irq_type);
360	    }
361	    HAL_UART_DmaTransmit(&(uart->handle), buf, size, (direction == RT_SERIAL_DMA_RX) ? DMA_PERIPH_TO_MEMORY : DMA_MEMORY_TO_PERIPH);
362	
363	    return 0;
364	}
365	#endif
