378	/**
379	 * Uart common interrupt process. This need add to uart ISR.
380	 *
381	 * @param serial serial device
382	 */
383	__ROM_USED void uart_isr(struct rt_serial_device *serial)
384	{
385	    struct sifli_uart *uart;
386	#ifdef RT_SERIAL_USING_DMA
387	    rt_size_t recv_total_index, recv_len;
388	    rt_base_t level;
389	#endif
390	
391	    RT_ASSERT(serial != RT_NULL);
392	
393	    uart = (struct sifli_uart *) serial->parent.user_data;
394	    RT_ASSERT(uart != RT_NULL);
395	
396	    /* UART in mode Receiver -------------------------------------------------*/
397	    if ((__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_RXNE) != RESET) &&
398	            (__HAL_UART_GET_IT_SOURCE(&(uart->handle), UART_IT_RXNE) != RESET))
399	    {
400	        rt_hw_serial_isr(serial, RT_SERIAL_EVENT_RX_IND);
401	    }
402	#ifdef RT_SERIAL_USING_DMA
403	    else if ((uart->uart_rx_dma_flag) && (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_IDLE) != RESET) &&
404	             (__HAL_UART_GET_IT_SOURCE(&(uart->handle), UART_IT_IDLE) != RESET))
405	    {
406	        __HAL_UART_CLEAR_IDLEFLAG(&uart->handle);
407	        level = rt_hw_interrupt_disable();
408	        recv_total_index = serial->config.bufsz - __HAL_DMA_GET_COUNTER(&(uart->dma_rx.handle));
409	        if (recv_total_index < uart->dma_rx.last_index)
410	            recv_len = serial->config.bufsz + recv_total_index - uart->dma_rx.last_index;
411	        else
412	            recv_len = recv_total_index - uart->dma_rx.last_index;
413	        uart->dma_rx.last_index = recv_total_index;
414	        rt_hw_interrupt_enable(level);
415	
416	        if (recv_len)
417	            rt_hw_serial_isr(serial, RT_SERIAL_EVENT_RX_DMADONE | (recv_len << 8));
418	    }
419	    else if ((uart->uart_tx_dma_flag)
420	             && (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TC) != RESET)
421	             && (__HAL_UART_GET_IT_SOURCE(&(uart->handle), UART_IT_TC) != RESET))
422	    {
423	        __HAL_UART_CLEAR_FLAG(&uart->handle, UART_CLEAR_TCF);
424	        uart->handle.gState = HAL_UART_STATE_READY;
425	        rt_hw_serial_isr(serial, RT_SERIAL_EVENT_TX_DMADONE);
426	        __HAL_UART_DISABLE_IT(&(uart->handle), UART_IT_TC);
427	    }
428	#endif
429	    else
430	    {
431	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_ORE) != RESET)
432	        {
433	            __HAL_UART_CLEAR_OREFLAG(&uart->handle);
434	        }
435	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_NE) != RESET)
436	        {
437	            __HAL_UART_CLEAR_NEFLAG(&uart->handle);
438	        }
439	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_FE) != RESET)
440	        {
441	            __HAL_UART_CLEAR_FEFLAG(&uart->handle);
442	        }
443	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_PE) != RESET)
444	        {
445	            __HAL_UART_CLEAR_PEFLAG(&uart->handle);
446	        }
447	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_CTS) != RESET)
448	        {
449	            UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_CTS);
450	        }
451	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TXE) != RESET)
452	        {
453	            UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_TXE);
454	        }
455	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_TC) != RESET)
456	        {
457	            UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_TC);
458	        }
459	        if (__HAL_UART_GET_FLAG(&(uart->handle), UART_FLAG_RXNE) != RESET)
460	        {
461	            UART_INSTANCE_CLEAR_FUNCTION(&(uart->handle), UART_FLAG_RXNE);
462	        }
463	    }
464	}
