851	__ROM_USED int rt_hw_usart_init2(struct sifli_uart *objs, struct sifli_uart_config *cfg, rt_size_t obj_num, rt_uint32_t baud_rate)
852	{
853	    struct serial_configure config = RT_SERIAL_CONFIG_DEFAULT;
854	    rt_err_t result = 0;
855	    rt_uint32_t flag;
856	
857	    config.baud_rate = baud_rate;
858	
859	    for (int i = 0; i < obj_num; i++)
860	    {
861	        objs[i].config = &cfg[i];
862	        objs[i].serial.ops = &sifli_uart_ops;
863	        objs[i].serial.config = config;
864	
865	        flag = RT_DEVICE_FLAG_RDWR | RT_DEVICE_FLAG_INT_RX | RT_DEVICE_FLAG_INT_TX;
866	
867	#if defined(RT_SERIAL_USING_DMA)
868	        if (objs[i].uart_rx_dma_flag)
869	        {
870	            flag |= RT_DEVICE_FLAG_DMA_RX;
871	        }
872	        if (objs[i].uart_tx_dma_flag)
873	        {
874	            flag |= RT_DEVICE_FLAG_DMA_TX;
875	        }
876	#endif
