127	/****************************************************************************
128	 * Name: uart_recvchars
129	 *
130	 * Description:
131	 *   This function is called from the UART interrupt handler when an
132	 *   interrupt is received indicating that are bytes available in the
133	 *   receive FIFO.  This function will add chars to head of receive buffer.
134	 *   Driver read() logic will take characters from the tail of the buffer.
135	 *
136	 ****************************************************************************/
137	
138	void uart_recvchars(FAR uart_dev_t *dev)
139	{
140	  FAR struct uart_buffer_s *rxbuf = &dev->recv;
141	#ifdef CONFIG_SERIAL_IFLOWCONTROL_WATERMARKS
142	  /* Pre-calculate the watermark level that we will need to test against. */
143	
144	  unsigned int watermark =
145	    (CONFIG_SERIAL_IFLOWCONTROL_UPPER_WATERMARK * rxbuf->size) / 100;
146	#endif
147	#if defined(CONFIG_TTY_SIGINT) || defined(CONFIG_TTY_SIGTSTP) || \
148	    defined(CONFIG_TTY_FORCE_PANIC) || defined(CONFIG_TTY_LAUNCH)
149	  int signo = 0;
150	#endif
