152	
153	  /* Loop putting characters into the receive buffer until there are no
154	   * further characters to available.
155	   */
156	
157	  while (uart_rxavailable(dev))
158	    {
159	      int nexthead = rxbuf->head + 1 < rxbuf->size ? rxbuf->head + 1 : 0;
160	      bool is_full = (nexthead == rxbuf->tail);
161	      FAR char *pbuf = NULL;
162	      char ch;
163	
164	#ifdef CONFIG_SERIAL_IFLOWCONTROL_WATERMARKS
165	      unsigned int nbuffered;
166	
167	      /* How many bytes are buffered */
168	
169	      if (rxbuf->head >= rxbuf->tail)
170	        {
171	          nbuffered = rxbuf->head - rxbuf->tail;
172	        }
173	      else
174	        {
175	          nbuffered = rxbuf->size - rxbuf->tail + rxbuf->head;
176	        }
177	
178	      /* Is the level now above the watermark level that we need to report? */
179	
180	      if (nbuffered >= watermark)
181	        {
182	          /* Let the lower level driver know that the watermark level has
183	           * been crossed.  It will probably activate RX flow control.
184	           */
185	
186	          if (uart_rxflowcontrol(dev, nbuffered, true))
187	            {
188	              /* Low-level driver activated RX flow control, exit loop now. */
189	
190	              break;
191	            }
192	        }
193	#elif defined(CONFIG_SERIAL_IFLOWCONTROL)
194	      /* Check if RX buffer is full and allow serial low-level driver to
195	       * pause processing. This allows proper utilization of hardware flow
196	       * control.
197	       */
198	
199	      if (is_full)
200	        {
201	          if (uart_rxflowcontrol(dev, rxbuf->size, true))
202	            {
203	              /* Low-level driver activated RX flow control, exit loop now. */
204	
205	              break;
206	            }
207	        }
208	#endif
209	
210	      /* Get this next character from the hardware */
211	
212	      if (dev->ops->recvbuf)
213	        {
214	          ssize_t ret;
215	
216	          if (!is_full)
217	            {
218	              if (rxbuf->tail > rxbuf->head)
219	                {
220	                  nbytes = rxbuf->tail - rxbuf->head - 1;
221	                }
222	              else if (rxbuf->tail)
223	                {
224	                  nbytes = rxbuf->size - rxbuf->head;
225	                }
226	              else
227	                {
228	                  nbytes = rxbuf->size - rxbuf->head - 1;
229	                }
230	
231	              pbuf = &rxbuf->buffer[rxbuf->head];
232	              ret = uart_recvbuf(dev, pbuf, nbytes);
233	              if (ret <= 0)
234	                {
235	                  continue;
236	                }
237	
238	              nbytes = ret;
239	              rxbuf->head += nbytes;
240	              if (rxbuf->head >= rxbuf->size)
241	                {
242	                  rxbuf->head = 0;
243	                }
244	            }
245	          else
246	            {
247	              pbuf = &ch;
248	              nbytes = 1;
249	
250	              ret = uart_recvbuf(dev, pbuf, nbytes);
251	              if (ret <= 0)
252	                {
253	                  continue;
254	                }
255	            }
256	        }
257	      else if(dev->ops->receive)
258	        {
259	          unsigned int status;
260	
261	          ch = uart_receive(dev, &status);
262	          pbuf = &ch;
263	          nbytes = 1;
264	
265	          /* If the RX buffer becomes full, then the serial data is
266	           * discarded. This is necessary because on most serial hardware,
267	           * you must read the data in order to clear the RX interrupt.
268	           * An option on some hardware might be to simply disable RX
269	           * interrupts until the RX buffer becomes non-FULL. However, that
270	           * would probably just cause the overrun to occur in hardware
271	           * (unless it has some large internal buffering).
272	           */
273	
274	          if (!is_full)
275	            {
276	              /* Add the character to the buffer */
