286	#if defined(CONFIG_TTY_SIGINT) || defined(CONFIG_TTY_SIGTSTP) || \
287	    defined(CONFIG_TTY_FORCE_PANIC) || defined(CONFIG_TTY_LAUNCH)
288	      signo = uart_check_special(dev, pbuf, nbytes);
289	#endif
290	    }
291	
292	  /* If any bytes were added to the buffer, inform any waiters there is new
293	   * incoming data available.
294	   */
295	
296	  if (rxbuf->head >= rxbuf->tail)
297	    {
298	      nbytes = rxbuf->head - rxbuf->tail;
299	    }
300	  else
301	    {
302	      nbytes = rxbuf->size - rxbuf->tail + rxbuf->head;
303	    }
304	
305	#ifdef CONFIG_SERIAL_TERMIOS
